const std = @import("std");
const types = @import("types.zig");

pub fn parseColorHex(hex: []const u8) types.Color {
    if (hex.len == 0) return .{ .r = 0, .g = 0, .b = 0, .a = 1 };

    var start_index: usize = 0;
    if (hex[0] == '#') start_index = 1;

    const hex_clean = hex[start_index..];

    if (hex_clean.len == 6) {
        const r = std.fmt.parseInt(u8, hex_clean[0..2], 16) catch 0;
        const g = std.fmt.parseInt(u8, hex_clean[2..4], 16) catch 0;
        const b = std.fmt.parseInt(u8, hex_clean[4..6], 16) catch 0;

        return .{
            .r = @as(f32, @floatFromInt(r)) / 255.0,
            .g = @as(f32, @floatFromInt(g)) / 255.0,
            .b = @as(f32, @floatFromInt(b)) / 255.0,
            .a = 1.0,
        };
    }

    return .{ .r = 0, .g = 0, .b = 0, .a = 1 };
}

pub fn parseFloat(value: []const u8) f32 {
    const trimmed = std.mem.trim(u8, value, " pxremem%");
    return std.fmt.parseFloat(f32, trimmed) catch 0.0;
}

pub fn parseDisplay(value: []const u8) types.DisplayMode {
    if (std.mem.eql(u8, value, "block")) return .Block;
    if (std.mem.eql(u8, value, "inline")) return .Inline;
    if (std.mem.eql(u8, value, "none")) return .None;
    return .Block;
}
