const std = @import("std");

pub const CdpClient = struct {
    stream: std.net.Stream,
    allocator: std.mem.Allocator,
    message_id: u32,

    pub fn init(allocator: std.mem.Allocator, host: []const u8, port: u16) !CdpClient {
        const address = try std.net.Address.parseIp4(host, port);
        const stream = try std.net.tcpConnectToAddress(address);

        return CdpClient{
            .stream = stream,
            .allocator = allocator,
            .message_id = 1,
        };
    }

    pub fn sendCommand(self: *CdpClient, method: []const u8, params_json: []const u8) !void {
        const id = self.message_id;
        self.message_id += 1;

        var json_buffer = std.ArrayList(u8).init(self.allocator);
        defer json_buffer.deinit();

        const writer = json_buffer.writer();
        try std.json.stringify(.{
            .id = id,
            .method = method,
            .params = std.json.Value{ .string = params_json }, 
        }, .{}, writer);

        try self.stream.writeAll(json_buffer.items);
    }

    pub fn navigate(self: *CdpClient, url: []const u8) !void {
        var params = std.ArrayList(u8).init(self.allocator);
        defer params.deinit();
        try std.json.stringify(.{ .url = url }, .{}, params.writer());

        try self.sendCommand("Page.navigate", params.items);
    }

    pub fn deinit(self: *CdpClient) void {
        self.stream.close();
    }
};
